def interleave_lists(a, b):
    result = []
    for x, y in zip(a, b):
        result.append(x)
        result.append(y)
    la, lb = len(a), len(b)
    if la > lb:
        result.extend(a[lb:])
    elif lb > la:
        result.extend(b[la:])
    return result

def reverse_integer(n):
    sign = -1 if n < 0 else 1
    reversed_digits = str(abs(n))[::-1]
    return sign * int(reversed_digits)

def is_palindrome_number(n):
    if n < 0:
        return False
    s = str(n)
    return s == s[::-1]

def is_perfect_number(n):
    if n < 1:
        return False
    total = 1 if n > 1 else 0
    i = 2
    while i * i <= n:
        if n % i == 0:
            total += i
            j = n // i
            if j != i:
                total += j
        i += 1
    return total == n

def collatz_length(n):
    count = 1
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        count += 1
    return count

def collatz_max_value(n):
    max_val = n
    while n != 1:
        if n % 2 == 0:
            n //= 2
        else:
            n = 3 * n + 1
        max_val = max(max_val, n)
    return max_val

def decimal_to_base(n, base):
    if n == 0:
        return "0"
    sign = "-" if n < 0 else ""
    n = abs(n)
    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = []
    while n > 0:
        result.append(digits[n % base])
        n //= base
    return sign + "".join(reversed(result))

def gcd_two(a, b):
    a, b = abs(a), abs(b)
    while b:
        a, b = b, a % b
    return a

def lcm_two(a, b):
    a, b = abs(a), abs(b)
    if a == 0 or b == 0:
        return 0
    x, y = a, b
    while y:
        x, y = y, x % y
    return a * b // x

def is_prime(n):
    if n < 2:
        return False
    if n < 4:
        return True
    if n % 2 == 0:
        return False
    i = 3
    while i * i <= n:
        if n % i == 0:
            return False
        i += 2
    return True

