def prime_factors(n):
    factors = []
    d = 2
    while d * d <= n:
        while n % d == 0:
            factors.append(d)
            n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def distinct_prime_factors(n):
    factors = []
    d = 2
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 1
    if n > 1:
        factors.append(n)
    return factors

def sum_of_divisors(n):
    if n == 0:
        return 0
    total = 0
    i = 1
    while i * i <= n:
        if n % i == 0:
            total += i
            j = n // i
            if j != i:
                total += j
        i += 1
    return total

def proper_divisors(n):
    divisors = []
    i = 1
    while i * i <= n:
        if n % i == 0:
            if i != n:
                divisors.append(i)
            j = n // i
            if j != i and j != n:
                divisors.append(j)
        i += 1
    return sorted(divisors)

def factorial(n):
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def is_perfect_square(n):
